// Find the email column, drop blanks and duplicates, cut into batches.
// Deduplication is not tidiness — every duplicate is a charged event.
const BATCH_SIZE = 100;
let EMAIL_COLUMN = '';

const rows = $input.all().map((i) => i.json);
if (rows.length === 0) return [];

// First column whose name mentions email. Set EMAIL_COLUMN above to override.
if (!EMAIL_COLUMN) {
  const header = Object.keys(rows[0]);
  EMAIL_COLUMN = header.find((h) => /e-?mail/i.test(h)) || header[0];
}

const seen = new Set();
const emails = [];
for (const row of rows) {
  const email = String(row[EMAIL_COLUMN] ?? '').trim();
  if (!email) continue;
  const key = email.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  emails.push(email);
}

const batches = [];
for (let i = 0; i < emails.length; i += BATCH_SIZE) {
  batches.push({ json: { emails: emails.slice(i, i + BATCH_SIZE), column: EMAIL_COLUMN } });
}
return batches;

// Greylisting is a server asking us to come back, not a bad address.
// These are the only rows worth spending a second charge on.
return $input.all().filter((i) => i.json.sub_status === 'greylisted');

// Three lists, three files. The buckets are the point of the product:
// 'review' is not a failure bucket, it is the set of addresses where an
// honest tool refuses to pretend it knows.
const send = [];
const review = [];
const drop = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.status) continue;
  const row = {
    email: r.email,
    status: r.status,
    sub_status: r.sub_status,
    score: r.score,
    catch_all: r.checks.catch_all,
    disposable: r.checks.disposable,
    role_based: r.checks.role_based,
    free_provider: r.checks.free_provider,
    mx_record: r.mx_record,
    verified_at: r.verified_at
  };
  if (r.status === 'deliverable') send.push(row);
  else if (r.status === 'undeliverable') drop.push(row);
  else review.push(row); // risky and unknown both need a human decision
}

function toCsv(rows) {
  if (rows.length === 0) return 'email,status,sub_status,score,catch_all,disposable,role_based,free_provider,mx_record,verified_at\n';
  const header = Object.keys(rows[0]);
  const escape = (v) => {
    const s = String(v ?? '');
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  return [header.join(','), ...rows.map((r) => header.map((h) => escape(r[h])).join(','))].join('\n') + '\n';
}

const file = (name, rows) => ({
  data: Buffer.from(toCsv(rows), 'utf8').toString('base64'),
  mimeType: 'text/csv',
  fileName: name,
  fileExtension: 'csv'
});

return [{
  json: { send_safe: send.length, review: review.length, drop: drop.length, total: send.length + review.length + drop.length },
  binary: {
    send_safe: file('send_safe.csv', send),
    review: file('review.csv', review),
    drop: file('drop.csv', drop)
  }
}];
